"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { SearchIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command"
import { Kbd } from "@/components/ui/kbd"
import { apps, type App } from "@/components/blocks/dashboard-01/data"

// Header search: pages of the current app first, then every other app.
// Opens with Ctrl/Cmd+K. Reads `apps` here, not as a prop: icon components
// can't be passed from a server component into this client component.
export function AppSearch() {
  const router = useRouter()
  const [open, setOpen] = useState(false)

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") {
        e.preventDefault()
        setOpen((o) => !o)
      }
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [])

  const go = (app: App, url: string) => {
    setOpen(false)
    // Other apps usually live on another origin: full navigation.
    if (app.current) router.push(url)
    else window.location.assign(url)
  }

  return (
    <>
      <Button
        render={<button />}
        variant="outline"
        onClick={() => setOpen(true)}
        aria-label="Search"
        // Narrow header: square icon button. Wide header: full search field.
        className="size-9 max-w-xl justify-center gap-2 px-0 font-normal text-muted-foreground shadow-none @2xl/header:w-full @2xl/header:min-w-0 @2xl/header:shrink @2xl/header:justify-start @2xl/header:px-2.5"
      >
        <SearchIcon />
        <span className="hidden flex-1 truncate text-left @2xl/header:block">
          Search pages, apps...
        </span>
        <Kbd className="hidden @2xl/header:inline-flex">Ctrl K</Kbd>
      </Button>
      <CommandDialog
        open={open}
        onOpenChange={setOpen}
        title="Search"
        description="Search this app and your other apps"
      >
        <CommandInput placeholder="Search pages and apps..." />
        <CommandList>
          <CommandEmpty>No results found.</CommandEmpty>
          {apps.map((app, i) => (
            <div key={app.name}>
              {i > 0 && <CommandSeparator />}
              <CommandGroup
                heading={app.current ? `${app.name} (this app)` : app.name}
              >
                {!app.current && (
                  <CommandItem
                    value={`${app.name} open app`}
                    onSelect={() => go(app, app.url)}
                  >
                    <app.icon />
                    Open {app.name}
                  </CommandItem>
                )}
                {app.pages.map((page) => (
                  <CommandItem
                    key={page.title}
                    value={`${app.name} ${page.title}`}
                    onSelect={() => go(app, page.url)}
                  >
                    <app.icon />
                    {page.title}
                  </CommandItem>
                ))}
              </CommandGroup>
            </div>
          ))}
        </CommandList>
      </CommandDialog>
    </>
  )
}

"use client"

import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar"
import type { NavGroup } from "@/components/blocks/dashboard-01/data"

export function NavMain({ groups }: { groups: NavGroup[] }) {
  return (
    <>
      {groups.map((group, i) => (
        <SidebarGroup key={group.label ?? i}>
          {group.label && (
            <SidebarGroupLabel className="text-[11px] tracking-wider uppercase">
              {group.label}
            </SidebarGroupLabel>
          )}
          <SidebarMenu>
            {group.items.map((item) => (
              <SidebarMenuItem key={item.title}>
                <SidebarMenuButton
                  tooltip={item.title}
                  isActive={item.active}
                  render={<a href={item.url} />}
                >
                  <item.icon />
                  <span>{item.title}</span>
                </SidebarMenuButton>
                {item.badge && (
                  <SidebarMenuBadge className="text-destructive">
                    {item.badge}
                  </SidebarMenuBadge>
                )}
              </SidebarMenuItem>
            ))}
          </SidebarMenu>
        </SidebarGroup>
      ))}
    </>
  )
}

"use client"

import { MoonIcon, SunIcon } from "lucide-react"
import { useTheme } from "next-themes"

import { Button } from "@/components/ui/button"

export function ThemeToggle() {
  const { resolvedTheme, setTheme } = useTheme()

  return (
    <Button
      render={<button />}
      variant="outline"
      size="icon"
      aria-label="Toggle theme"
      onClick={() => setTheme(resolvedTheme === "dark" ? "light" : "dark")}
    >
      {/* Both icons render; CSS picks one, so SSR and client agree. */}
      <MoonIcon className="dark:hidden" />
      <SunIcon className="hidden dark:block" />
    </Button>
  )
}

import type { ComponentType } from "react"

import { Logo } from "@/components/docs/logo"
import {
  ChartPieIcon,
  GlobeIcon,
  HistoryIcon,
  KeyRoundIcon,
  LayoutGridIcon,
  LifeBuoyIcon,
  MailIcon,
  MapIcon,
  PackageIcon,
  type LucideIcon,
  Settings2Icon,
  ShieldCheckIcon,
  TerminalIcon,
  UsersIcon,
  ServerIcon,
} from "lucide-react"

// Sample data. Replace with your product, orgs, user and routes.

export type NavItem = {
  title: string
  url: string
  icon: LucideIcon
  active?: boolean
  badge?: string
}

export type NavGroup = { label?: string; items: NavItem[] }

export type App = {
  name: string
  url: string
  icon: LucideIcon | ComponentType<{ className?: string }>
  // Current app: results open with the router instead of a full navigation.
  current?: boolean
  pages: { title: string; url: string }[]
}

export const product = {
  name: "SwiftlyLabs",
  logo: Logo,
}

export const user = {
  name: "Jane Doe",
  role: "Org admin",
  avatar: "",
}

export const orgs = [
  { name: "swiftlylabs-prod", plan: "Enterprise" },
  { name: "swiftlylabs-staging", plan: "Enterprise" },
  { name: "side-project", plan: "Free" },
]

export const navGroups: NavGroup[] = [
  {
    items: [
      { title: "Overview", url: "#", icon: LayoutGridIcon, active: true },
      { title: "Nodes", url: "#", icon: ServerIcon, badge: "4 offline" },
      { title: "Apps", url: "#", icon: PackageIcon, badge: "2 degraded" },
      { title: "Terminal", url: "#", icon: TerminalIcon },
