// What the header search covers: this app first, then the others.
export const apps: App[] = [
  {
    name: product.name,
    url: "#",
    icon: product.logo,
    current: true,
    pages: [...navGroups.flatMap((g) => g.items), settingsItem].map((i) => ({
      title: i.title,
      url: i.url,
    })),
  },
  {
    name: "Analytics",
    url: "#",
    icon: ChartPieIcon,
    pages: [
      { title: "Overview", url: "#" },
      { title: "Reports", url: "#" },
    ],
  },
  {
    name: "Mail",
    url: "#",
    icon: MailIcon,
    pages: [
      { title: "Inbox", url: "#" },
      { title: "Campaigns", url: "#" },
    ],
  },
  {
    name: "Support",
    url: "#",
    icon: LifeBuoyIcon,
    pages: [
      { title: "Tickets", url: "#" },
      { title: "Knowledge base", url: "#" },
    ],
  },
]
